float spec = pow(max(dot(reflectDir, lightDir), 0.0), 32.0);
// Funky palette color using original method
vec4 baseColor = (1.0 + sin(0.5 * q.z + length(p.xyz - q.xyz) + vec4( 0.0 , 4.0 , 3.0 , 6.0 )))
/ (0.5 + 2.0 * dot(q.xy, q.xy));
#ifdef bass_smooth
float fac = (int)vis_version > 2 ? 1.0 + vis_intensity+vis_shift : (1 + 4.0 * smoothstep( 0.0 , 2.0 ,(int)vis_version == 1 ? bass_smooth : audioLowSmooth))*vis_intensity+vis_shift;
#else
float fac = 1 + 1.0 * smoothstep( 0.0 , 2.0 ,audioLowSmooth);
#endif
// Combine base color + environment reflection + specular highlight
vec3 finalColor = baseColor.rgb * fac * 0.1 + envColor * 0.9 + vec3(spec,spec,spec) * 1.2;
// Brightness weighted accumulation
col.rgb += finalColor / d;
z += 0.7 * d;
}
